// BolsServiceServer is the server API for BolsService service.
// All implementations should embed UnimplementedBolsServiceServer
// for forward compatibility
type BolsServiceServer interface {
	// GetFileStat reads file information from the labstation.
	GetFileStat(context.Context, *GetFileStatRequest) (*GetFileStatResponse, error)
	// GetFile gets a file from labstation.
	GetFile(*GetFileRequest, BolsService_GetFileServer) error
	// PutFile puts a file on labstation.
	// If the directory of destination path does not exist, this service
	// will also create the directory.
	PutFile(BolsService_PutFileServer) error
	// DownloadFile downloads a file on labstation based on the specified url
	// by sending a http GET request to the url.
	DownloadFile(context.Context, *DownloadFileRequest) (*DownloadFileResponse, error)
	// RemoveFile removes a file on labstation/container.
	RemoveFile(context.Context, *RemoveFileRequest) (*RemoveFileResponse, error)
	// DirInfo reads a directory info from the labstation.
	GetDirInfo(context.Context, *GetDirInfoRequest) (*GetDirInfoResponse, error)
	// MakeDir makes a directory on the labstation.
	MakeDir(context.Context, *MakeDirRequest) (*MakeDirResponse, error)
	// MakeTempDir makes a directory on the labstation.
	MakeTempDir(context.Context, *MakeTempDirRequest) (*MakeTempDirResponse, error)
	// RemoveDir removes a directory from labstation/container.
	RemoveDir(context.Context, *RemoveDirRequest) (*RemoveDirResponse, error)
	// DMesg returns the output from the dmesg command.
	DMesg(*DMesgRequest, BolsService_DMesgServer) error
	// WriteFileByBlock write data to a file by blocks.
	// For most implementation of this service, it will be simple
	// call to "dd <filename> oflag=sync conv=notrunc,nocreat".
	WriteFileByBlock(BolsService_WriteFileByBlockServer) error
	// ReadFileByBlock reads data by Block
	// For most implementation of this service, it will be simple
	// call to "dd".
	ReadFileByBlock(*ReadFileByBlockRequest, BolsService_ReadFileByBlockServer) error
	// RunMount runs the "mount" command on the labstation.
	RunMount(context.Context, *RunMountRequest) (*RunMountResponse, error)
	// RunUMount runs the "umount" command on the labstation.
	RunUMount(context.Context, *RunUMountRequest) (*RunUMountResponse, error)
	// DownloadImageToUSB downloads an image and writes it to a USB drive.
	DownloadImageToUSB(context.Context, *DownloadImageToUSBRequest) (*DownloadImageToUSBResponse, error)
	// StartServod runs a servod daemon.
	StartServod(context.Context, *StartServodRequest) (*StartServodResponse, error)
	// StopServod stops the servod daemon.
	StopServod(context.Context, *StopServodRequest) (*StopServodResponse, error)
	// StartEmptyContainer starts a servod container without running a servod
	// process. For BOLS services that run servod in a container, this is
	// useful for maintenance or debugging, such as when updating servo
	// firmware. If the BOLS service does not use a container, this RPC will do
	// nothing.
	// When work in the empty container is complete, users should call StopServod
	// to clean up and remove the container.
	StartEmptyContainer(context.Context, *StartEmptyContainerRequest) (*StartEmptyContainerResponse, error)
	// GetServodStatus gets the current status of servod.
	GetServodStatus(context.Context, *GetServodStatusRequest) (*GetServodStatusResponse, error)
	// HWInitServod calls hwinit of servod.
	HWInitServod(context.Context, *HWInitServodRequest) (*HWInitServodResponse, error)
	// DocServod read a servod control documentation.
	DocServod(context.Context, *DocServodRequest) (*DocServodResponse, error)
	// GetServod gets a servod control value.
	GetServod(context.Context, *GetServodRequest) (*GetServodResponse, error)
	// SetServod sets value to a servod control.
	SetServod(context.Context, *SetServodRequest) (*SetServodResponse, error)
	// GetServodVersion reads version of started servod.
	GetServodVersion(context.Context, *GetServodVersionRequest) (*GetServodVersionResponse, error)
	// EchoServod calls echo method of servod.
	EchoServod(context.Context, *EchoServodRequest) (*EchoServodResponse, error)
	// GetServoTopology gets the servo topology.
	GetServoTopology(context.Context, *GetServoTopologyRequest) (*GetServoTopologyResponse, error)
	// UpdateServoFirmware updates the firmware of servo devices connected to the
	// same hub as the servo with the given serial. It can update specific servo
	// types or all qualified servo types. The firmware channel (stable, dev,
	// etc.) and whether to force the update can be specified. Note: The servod
	// process must be stopped before calling this API, as the update will fail if
	// servod is running.
	UpdateServoFirmware(context.Context, *UpdateServoFirmwareRequest) (*UpdateServoFirmwareResponse, error)
	// RunFutility run futility tool on labstation.
	RunFutility(context.Context, *RunFutilityRequest) (*RunFutilityResponse, error)
	// RunFlashEC run EC firmware flashing from the servo.
	// In most of implementation, it runs flash_ec tool on labstation.
	RunFlashEC(context.Context, *RunFlashECRequest) (*RunFlashECResponse, error)
	// RunGSCTool run gsctool on labstation.
	// Example:
	//  gsctool -n 1002D052-9066B226 -f
	//  Params: ["-n", "1002D052-9066B226", "-f" ]
	RunGSCTool(context.Context, *RunGSCToolRequest) (*RunGSCToolResponse, error)
	// RunUARTStressTester runs uart_stress_tester.py on labstation.
	// uart_stress_tester.py repeats sending a uart console command
	// to each UART device for a given time, and check if output
	// has any missing characters.
	// Example:
	//  uart_stress_tester.py /dev/ttyUSB2 --time 3600
	RunUARTStressTester(context.Context, *RunUARTStressTesterRequest) (*RunUARTStressTesterResponse, error)
	GetDolosVersion(context.Context, *GetDolosVersionRequest) (*GetDolosVersionResponse, error)
	// UpdateDolosVersion will update the Dolos version if version does
	// not match expected one.
	UpdateDolosVersion(context.Context, *UpdateDolosVersionRequest) (*UpdateDolosVersionResponse, error)
	// GetDolosStatus read the status of the Dolos.
	GetDolosStatus(context.Context, *GetDolosStatusRequest) (*GetDolosStatusResponse, error)
	// FindDolosUART finds the UART of the Dolos.
	FindDolosUART(context.Context, *FindDolosUARTRequest) (*FindDolosUARTResponse, error)
}

